def shift_scores(A,B):
    H=len(A); wa=len(A[0]); wb=len(B[0]); scores=[]
    # dx is B origin in A coordinates
    for dx in range(-wb+1,wa):
        xs=range(max(0,dx),min(wa,dx+wb))
        n=len(list(xs))*H
        m=sum(A[r][x]==B[r][x-dx] for r in range(H) for x in range(max(0,dx),min(wa,dx+wb)))
        scores.append((m,n,dx,m/n if n else 0))
    return sorted(scores,key=lambda z:(z[0],z[3]),reverse=True)
